/**
 * Generates CSS custom properties and TypeScript types from tokens/tokens.json (UI-FND-01) and
 * verifies every contrast pair (UXA-003): the build fails when a pair is below its threshold.
 *
 *   vite-node scripts/build-tokens.ts           write generated files
 *   vite-node scripts/build-tokens.ts --check   fail if generated files are stale
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const tokens = JSON.parse(readFileSync(`${root}tokens/tokens.json`, 'utf8')) as Tokens;

type Tokens = {
  raw: Record<string, string>;
  semantic: Record<string, string>;
  chartSeries: Array<{ token: string; marker: string; dash: string; name: string }>;
  space: Record<string, number>;
  radius: Record<string, number>;
  elevation: Record<string, string>;
  font: {
    family: string;
    styles: Record<string, { size: number; line: number; weight: number; letterSpacing?: string }>;
  };
  breakpoint: Record<string, number>;
  layout: Record<string, number>;
  target: Record<string, number>;
  focus: { width: number; offset: number };
  motion: Record<string, number>;
  contrast: Array<{
    fg: string;
    bg: string;
    min: number;
    use: string;
    waiver?: { min: number; reason: string };
  }>;
};

import { contrastRatio } from './lib/contrast';

/** Resolve a semantic or raw token name to its hex value. */
const resolve = (name: string): string => {
  const raw = tokens.semantic[name] ?? name;
  const hex = tokens.raw[raw];
  if (!hex) throw new Error(`Unknown colour token "${name}"`);
  return hex;
};

// ---- generation -----------------------------------------------------------------------------

const px = (n: number) => `${n}px`;
const lines: string[] = [];
const out = (s = '') => lines.push(s);

out('/* GENERATED by scripts/build-tokens.ts from tokens/tokens.json. Do not edit by hand. */');
out(':root {');
out('  /* raw palette: reference only through semantic tokens */');
for (const [k, v] of Object.entries(tokens.raw)) out(`  --ui-raw-${k}: ${v};`);
out('');
out('  /* semantic colours (tenant theming overrides brand-derived tokens only, spec 3.6) */');
for (const [k, v] of Object.entries(tokens.semantic)) out(`  --ui-color-${k}: var(--ui-raw-${v});`);
out('');
out('  /* chart series */');
tokens.chartSeries.forEach((s, i) => out(`  --ui-chart-${i + 1}: var(--ui-raw-${s.token});`));
out('');
for (const [k, v] of Object.entries(tokens.space)) out(`  --ui-space-${k}: ${px(v)};`);
for (const [k, v] of Object.entries(tokens.radius)) out(`  --ui-radius-${k}: ${px(v)};`);
for (const [k, v] of Object.entries(tokens.elevation)) out(`  --ui-elevation-${k}: ${v};`);
out(`  --ui-font-family: ${tokens.font.family};`);
for (const [k, v] of Object.entries(tokens.font.styles)) {
  out(`  --ui-font-${k}-size: ${px(v.size)};`);
  out(`  --ui-font-${k}-line: ${px(v.line)};`);
  out(`  --ui-font-${k}-weight: ${v.weight};`);
  if (v.letterSpacing) out(`  --ui-font-${k}-tracking: ${v.letterSpacing};`);
}
for (const [k, v] of Object.entries(tokens.layout)) out(`  --ui-layout-${k}: ${px(v)};`);
for (const [k, v] of Object.entries(tokens.target)) out(`  --ui-target-${k}: ${px(v)};`);
out(`  --ui-focus-width: ${px(tokens.focus.width)};`);
out(`  --ui-focus-offset: ${px(tokens.focus.offset)};`);
for (const [k, v] of Object.entries(tokens.motion)) out(`  --ui-motion-${k}: ${v}ms;`);
out('}');
out('');
out('/* Reduced motion: no transitions or animation (UI-FND-07). */');
out('@media (prefers-reduced-motion: reduce) {');
out('  :root {');
for (const k of Object.keys(tokens.motion)) out(`    --ui-motion-${k}: 0ms;`);
out('  }');
out('}');
out('');
out('/* Breakpoints (logical, mobile-first) for reference in media queries:');
for (const [k, v] of Object.entries(tokens.breakpoint)) out(`   ${k}: ${px(v)}`);
out('*/');
const css = `${lines.join('\n')}\n`;

const colorNames = Object.keys(tokens.semantic);
const ts = `/* GENERATED by scripts/build-tokens.ts from tokens/tokens.json. Do not edit by hand. */
export const tokens = ${JSON.stringify(
  {
    semantic: Object.fromEntries(Object.entries(tokens.semantic).map(([k]) => [k, resolve(k)])),
    chartSeries: tokens.chartSeries.map((s) => ({ ...s, hex: resolve(s.token) })),
    space: tokens.space,
    radius: tokens.radius,
    font: tokens.font.styles,
    breakpoint: tokens.breakpoint,
    layout: tokens.layout,
    target: tokens.target,
    motion: tokens.motion,
  },
  null,
  2,
)} as const;

export type SemanticColorToken = ${colorNames.map((n) => `'${n}'`).join(' | ')};
export type SpaceToken = ${Object.keys(tokens.space)
  .map((n) => `'${n}'`)
  .join(' | ')};
export type RadiusToken = ${Object.keys(tokens.radius)
  .map((n) => `'${n}'`)
  .join(' | ')};
export type FontStyleToken = ${Object.keys(tokens.font.styles)
  .map((n) => `'${n}'`)
  .join(' | ')};

/** CSS custom property reference for a semantic colour, e.g. cssColor('text-primary'). */
export const cssColor = (name: SemanticColorToken): string => \`var(--ui-color-\${name})\`;
`;

// ---- verify contrast -------------------------------------------------------------------------

const failures: string[] = [];
const contrastReport = tokens.contrast.map((p) => {
  const ratio = contrastRatio(resolve(p.fg), resolve(p.bg));
  if (ratio < (p.waiver?.min ?? p.min))
    failures.push(`${p.fg} on ${p.bg} (${p.use}): ${ratio.toFixed(2)}:1 < ${p.min}:1`);
  return { ...p, ratio };
});

const targets: Array<[string, string]> = [
  [`${root}app/assets/css/tokens.css`, css],
  [`${root}app/tokens.generated.ts`, ts],
];

if (failures.length > 0) {
  console.error('FAIL: contrast');
  for (const f of failures) console.error(`  - ${f}`);
  process.exit(1);
}

// Windows checkouts with core.autocrlf give working copies CRLF; compare content, not line endings.
const normalizeEol = (s: string) => s.replace(/\r\n/g, '\n');

if (process.argv.includes('--check')) {
  const stale = targets.filter(
    ([path, content]) => !existsSync(path) || normalizeEol(readFileSync(path, 'utf8')) !== content,
  );
  if (stale.length > 0) {
    console.error(
      `FAIL: tokens:check - stale generated files: ${stale.map(([p]) => p).join(', ')}`,
    );
    console.error('Run: npm run tokens:build -w @imp/ui');
    process.exit(1);
  }
  console.warn(`OK: tokens up to date, ${contrastReport.length} contrast pairs pass`);
} else {
  for (const [path, content] of targets) writeFileSync(path, content);
  console.warn(`OK: tokens generated, ${contrastReport.length} contrast pairs pass`);
}
